// Il corpo GREZZO, byte per byte, e la firma che lo accompagna.
//
// Gemello del nodo omonimo di `calcom-consulenze`, e per la stessa ragione: la
// firma si calcola sui byte esatti che sono arrivati. Un JSON parsato e
// riserializzato da n8n da' una firma diversa anche a contenuto identico —
// l'ordine delle chiavi, gli spazi e il formato dei numeri non sopravvivono al
// giro. Il nodo Webhook ha "Raw Body" acceso e qui si decodifica.
//
// Quello che cambia rispetto a Cal.com e' solo il nome dell'header:
// `stripe-signature` invece di `x-cal-signature-256`. Il contenuto e' diverso
// (`t=<timestamp>,v1=<hex>`, con la finestra di tolleranza) ma qui non si
// guarda: tutta la verifica vive nella funzione Postgres `stripe_webhook()`
// della migration 0039. Questo nodo non decide niente, e' idraulica.
//
// Se il corpo grezzo non arriva, FALLISCE di proposito invece di ripiegare su
// una riserializzazione: il ripiego silenzioso darebbe "firma_non_valida" su
// ogni messaggio, che e' il modo peggiore di rompersi — sembra un problema di
// segreti e non lo e'.
const item = $input.first();

const b64 = item.binary && item.binary.data && item.binary.data.data;
if (!b64) {
  throw new Error(
    'Il nodo Webhook non ha consegnato il corpo grezzo. Controlla che l\'opzione ' +
    '"Raw Body" sia accesa: senza i byte originali la firma non si puo\' verificare.'
  );
}

const corpo = Buffer.from(b64, 'base64').toString('utf8');
const headers = item.json.headers || {};
const firma = headers['stripe-signature'] || '';

return [{ json: { corpo, firma } }];
